package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class JsonParserSequence_nextToken_TriageGen2Test {

    /**
     * Test case 1: delegate.nextToken() returns a non-null token immediately.
     * Covers the first 'if (t != null) return t;' branch.
     */
    @Test
    public void testNextToken_ReturnsImmediately() throws IOException, JsonParseException {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.nextToken()).thenReturn(JsonToken.START_OBJECT);

        // Using the static factory method provided in the description
        JsonParserSequence sequence = JsonParserSequence.createFlattened(mockParser, mock(JsonParser.class));

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(mockParser, times(1)).nextToken();
    }

    /**
     * Test case 2: delegate.nextToken() returns null, switchToNext() returns true, 
     * and the next delegate returns a non-null token.
     * Covers the 'while (switchToNext())' loop and the 'if (t != null) return t;' inside the loop.
     */
    @Test
    public void testNextToken_SwitchesToNextAndReturnsToken() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        // createFlattened wraps these parsers
        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(parser1).nextToken();
        verify(parser2).nextToken();
    }

    /**
     * Test case 3: All delegates return null, switchToNext() returns false.
     * Covers the case where the loop terminates and returns null.
     */
    @Test
    public void testNextToken_AllParsersEmptyReturnsNull() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(null);

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);

        JsonToken result = sequence.nextToken();

        assertNull(result);
        verify(parser1).nextToken();
        verify(parser2).nextToken();
    }

    /**
     * Test case 4: delegate.nextToken() throws IOException.
     * Covers exception propagation.
     */
    @Test(expected = IOException.class)
    public void testNextToken_ThrowsIOException() throws IOException, JsonParseException {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.nextToken()).thenThrow(new IOException("Test IOException"));

        JsonParserSequence sequence = JsonParserSequence.createFlattened(mockParser, mock(JsonParser.class));

        sequence.nextToken();
    }

    /**
     * Test case 5: delegate.nextToken() throws JsonParseException.
     * Covers exception propagation.
     */
    @Test(expected = JsonParseException.class)
    public void testNextToken_ThrowsJsonParseException() throws IOException, JsonParseException {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.nextToken()).thenThrow(new JsonParseException(null, "Test Parse Exception"));

        JsonParserSequence sequence = JsonParserSequence.createFlattened(mockParser, mock(JsonParser.class));

        sequence.nextToken();
    }
}
